/* Memory home — node 7188:1983 */
:root {
  --text-primary: #1a1f3c;
  --text-secondary: #565c79;
  --text-tertiary: #717794;
  --neutral-700: #3d456b;
  --bg-surface: #f5f6fa;
  --bg-canvas: #ffffff;
  --space-8: 8px;
  --space-12: 12px;
  --space-16: 16px;
  --space-24: 24px;
}

.memory-title {
  font: 600 24px/32px "SF Pro Text", -apple-system, sans-serif;
  color: var(--text-primary);
}

.memory-intro {
  font: 400 15px/22px "SF Pro Text", -apple-system, sans-serif;
  color: var(--text-secondary);
}

/* "What you've told PC Chat(TM)" summary card */
.memory-summary {
  background: var(--bg-canvas);
  border-radius: 24px;
  padding: var(--space-16);
  display: flex;
  flex-direction: column;
  gap: var(--space-12);
}

.memory-summary__heading {
  font: 600 18px/28px "SF Pro Text", -apple-system, sans-serif;
  color: var(--text-primary);
}

.memory-summary__body {
  font: 400 15px/22px "SF Pro Text", -apple-system, sans-serif;
  color: var(--neutral-700);
}

.memory-summary__updated {
  font: 400 12px/18px "SF Pro Text", -apple-system, sans-serif;
  color: var(--text-tertiary);
}

/* "Top of mind" list */
.memory-item__title {
  font: 600 15px/22px "SF Pro Text", -apple-system, sans-serif;
  color: var(--text-primary);
}

.memory-item__updated {
  font: 400 14px/20px "SF Pro Text", -apple-system, sans-serif;
  color: var(--text-secondary);
}

