// Memory home, as returned by the Figma MCP for node 7188:1983. Trimmed to the
// structure that matters — status bar and icon assets removed.
//
// Note the two bindings of text/secondary below: the intro falls back to #565c79,
// the card heading to #3d456b. Same token, same frame, two values.

export default function MemoryHome() {
  return (
    <div className="bg-[var(--bg/canvas,white)] rounded-[48px] size-full" data-node-id="7188:1983">
      <div className="absolute flex flex-col gap-[32px] left-0 right-0 top-[122px] px-[16px] pt-[24px] pb-[16px]" data-node-id="7188:1988" data-name="Content">

        <header className="flex flex-col gap-[4px] px-[8px]" data-node-id="7188:1990">
          <p className="text-[24px] leading-[32px] font-['SF_Pro_Text:Semibold'] text-[color:var(--text/primary,#1a1f3c)]" data-node-id="7188:1991">
            Memory
          </p>
          <p className="text-[length:var(--font/size/text-md,15px)] leading-[var(--font/lh/text-md,22px)] text-[color:var(--text/secondary,#565c79)]" data-node-id="7188:1992">
            Memories are details you&rsquo;ve shared about your health, family, lifestyle, and
            preferences. They help personalize PC Chat&trade; answers and you can update or
            delete them anytime.
          </p>
        </header>

        {/* Figma layer name: "What I know about you" — heading text says otherwise */}
        <section
          className="flex flex-col gap-[8px] w-[359px] rounded-[20px] border-2 border-[var(--new-neutrals/white,white)] bg-[var(--bg/surface,#f5f6fa)] p-[var(--space/16,16px)] backdrop-blur-[calc(var(--blur/glass-sm,20px)/2)]"
          data-node-id="7188:1993"
          data-name="What I know about you"
        >
          <BrandMark className="size-[32px]" />

          <p className="text-[length:var(--font/size/text-lg,18px)] leading-[var(--font/lh/text-lg,28px)] text-[color:var(--text/secondary,#3d456b)]" data-node-id="7188:1998">
            What you&rsquo;ve told PC Chat&trade;
          </p>

          {summary.paragraphs.map((text) => (
            <p key={text} className="text-[length:var(--font/size/text-sm,14px)] leading-[var(--font/lh/text-sm,20px)] text-[color:var(--neutral/700,#3d456b)]">
              {text}
            </p>
          ))}

          <p className="pt-[8px] text-[length:var(--font/size/text-xs,12px)] leading-[var(--font/lh/text-xs,18px)] text-[color:var(--text/tertiary,#717794)]" data-node-id="7188:2002">
            Last updated {summary.updatedLabel}
          </p>
        </section>

        {/* Groups: "Top of mind", "Your current health", … separated by 1px #dddfeb rules */}
        {groups.map((group) => (
          <section key={group.title} className="flex flex-col gap-[8px]">
            <h2 className="px-[8px] text-[length:var(--font/size/text-md,15px)] leading-[var(--font/lh/text-md,22px)] text-[color:var(--text/primary,#1a1f3c)]">
              {group.title}
            </h2>

            <ul className="flex flex-col">
              {group.items.map((item) => (
                <li key={item.id} className="flex min-h-[40px] items-center p-[8px]">
                  <div className="flex flex-1 flex-col gap-[2px]">
                    <p className="truncate text-[15px] leading-[var(--font/lh/text-md,22px)] text-[color:var(--text/primary,#1a1f3c)]">
                      {item.text}
                    </p>
                    <p className="text-[length:var(--font/size/text-xs,12px)] leading-[var(--font/lh/text-xs,18px)] text-[color:var(--new-neutrals/darkest-grey,#565c79)]">
                      {item.updatedLabel}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          </section>
        ))}
      </div>

      {/* Search is a pinned button over a white scrim, not an inline field */}
      <div className="absolute bottom-0 left-0 h-[140px] w-[393px]" data-node-id="7340:57517" data-name="Search with overlay">
        <div className="absolute bottom-0 h-[140px] w-full bg-gradient-to-b from-white/0 via-white/70 to-white/90" />
        <button className="absolute left-[24px] top-[64px] flex h-[44px] w-[345px] items-center gap-[8px] rounded-full border-2 border-white bg-[var(--bg/white-subtle,rgba(255,255,255,0.4))] px-[16px]" data-node-id="7340:57519">
          <MagnifyingGlass className="size-[16px]" />
          <span className="text-[length:var(--font/size/text-md,15px)] text-[color:var(--text/tertiary,#717794)]">Search</span>
        </button>
      </div>
    </div>
  );
}

